# Count non-background cells and create a frequency map
from collections import Counter

def count_cells(grid, exclude_bg):
    counts = Counter()
    for row in grid:
        for cell in row:
            if cell != exclude_bg:
                counts[cell] += 1
    return counts

input_counts = count_cells(demo_input, bg_in)
output_counts = count_cells(demo_output, bg_out)

print("Input non-background counts:")
