print("\nOutput non-background counts:")
print(output_counts)

# Check if counts are preserved
for color in input_counts:
    if color in output_counts:
        if input_counts[color] != output_counts[color]:
            print(f"Color {color}: input count {input_counts[color]}, output count {output_counts[color]}")
    else:
        print(f"Color {color}: input count {input_counts[color]}, not found in output")

for color in output_counts:
    if color not in input_counts:
        print(f"Color {color}: NOT in input, output count {output_counts[color]}")

